INSERT INTO articles (title, category, content, published_date, view_count) VALUES
('Как правильно считать калории', 'nutrition', 'Подсчёт калорий — один из самых эффективных способов контролировать вес. Для начала определите свою суточную норму: для женщин это около 2000 ккал, для мужчин — 2500 ккал. Используйте формулу Харриса-Бенедикта для точного расчёта с учётом вашего веса, роста, возраста и уровня активности. Отслеживайте питание в дневнике и взвешивайте продукты для точности.', CURRENT_DATE - INTERVAL '10 days', 1240),
('5 принципов здорового питания', 'nutrition', 'Первый принцип — разнообразие. Включайте в рацион овощи, фрукты, белки, сложные углеводы и полезные жиры. Второй — регулярность: 3-5 приёмов пищи в день поддерживают стабильный уровень сахара в крови. Третий — умеренность: не переедайте. Четвёртый — гидратация: пейте 1,5-2 литра воды в день. Пятый — минимум обработанных продуктов.', CURRENT_DATE - INTERVAL '7 days', 890),
('Кардио для похудения: мифы и реальность', 'training', 'Многие считают, что чем больше кардио — тем лучше результат. Это миф. Оптимальный объём — 150-300 минут умеренного кардио в неделю. Интервальные тренировки (HIIT) сжигают больше калорий за меньшее время. Сочетайте кардио с силовыми тренировками: мышечная масса ускоряет метаболизм даже в покое.', CURRENT_DATE - INTERVAL '5 days', 2100),
('Силовые тренировки для начинающих', 'training', 'Начните с базовых упражнений: приседания, жим лёжа, становая тяга, подтягивания. Эти движения задействуют несколько мышечных групп одновременно. Начинайте с небольших весов и правильной техники — это важнее, чем тяжёлые веса. Тренируйтесь 3 раза в неделю с днями отдыха между тренировками. Прогрессия нагрузки — ключ к росту.', CURRENT_DATE - INTERVAL '3 days', 670),
('Сон и восстановление: почему это важно', 'health', 'Во время сна организм вырабатывает гормон роста, восстанавливает мышцы и консолидирует память. Недостаток сна повышает уровень кортизола, что приводит к накоплению жира и потере мышц. Спите 7-9 часов в сутки. Создайте ритуал отхода ко сну: тёмная прохладная комната, отсутствие экранов за час до сна, одно и то же время подъёма.', CURRENT_DATE - INTERVAL '1 day', 430),
('Управление стрессом через питание', 'health', 'Хронический стресс влияет на выбор продуктов: мы тянемся к сладкому и жирному. Магний (тёмный шоколад, орехи, шпинат) снижает уровень кортизола. Омега-3 жирные кислоты (лосось, льняное семя) улучшают настроение. Пробиотики (йогурт, кефир) поддерживают ось кишечник-мозг. Ешьте регулярно — пропуск еды усиливает тревожность.', CURRENT_DATE, 310);
INSERT INTO workouts (title, description, category, duration_minutes, difficulty, calories, view_count) VALUES
('Утренняя пробежка', 'Лёгкая пробежка для бодрого начала дня. Подходит для любого уровня подготовки.', 'cardio', 30, 'beginner', 250, 890),
('HIIT: Сжигаем жир', 'Высокоинтенсивная интервальная тренировка для максимального жиросжигания за минимальное время.', 'cardio', 25, 'intermediate', 400, 1560),
('Силовая: Грудь и трицепс', 'Классическая тренировка на грудные мышцы и трицепс с базовыми упражнениями.', 'strength', 50, 'intermediate', 320, 740),
('Силовая: Спина и бицепс', 'Тренировка на мышцы спины и бицепс. Формирует атлетический торс.', 'strength', 50, 'intermediate', 300, 620),
('Силовая: Ноги и плечи', 'Комплексная тренировка на нижнюю часть тела и плечи.', 'strength', 60, 'advanced', 450, 530),
('Йога: Утренняя растяжка', 'Мягкая йога-практика для пробуждения тела и улучшения гибкости.', 'flexibility', 20, 'beginner', 100, 1100),
('Пилатес: Укрепление кора', 'Тренировка глубоких мышц живота и спины. Улучшает осанку и снижает боли в спине.', 'flexibility', 40, 'beginner', 180, 780),
('Табата для всего тела', 'Протокол Табата: 20 сек работа, 10 сек отдых. Максимальная интенсивность.', 'cardio', 20, 'advanced', 350, 2200);
