INSERT INTO recipes (title, description, ingredients, instructions, cooking_time, servings, calories, protein, carbs, fats, category, tags, is_active) VALUES
('Овсяная каша с ягодами', 'Питательный завтрак с антиоксидантами', '["100г овсяных хлопьев", "200мл молока", "50г черники", "50г малины", "1 ч.л. мёда", "щепотка соли"]', 'Залейте овсянку молоком и доведите до кипения. Варите 5 минут на слабом огне, помешивая. Добавьте соль и мёд. Выложите в тарелку и украсьте ягодами.', 10, 1, 320, 12.0, 55.0, 6.0, 'breakfast', '["вегетарианское", "быстро", "полезное"]', true),
('Куриная грудка с овощами', 'Лёгкий белковый обед для поддержания мышц', '["200г куриной грудки", "150г брокколи", "1 болгарский перец", "2 зубчика чеснока", "1 ст.л. оливкового масла", "соль и перец по вкусу"]', 'Нагрейте масло на сковороде. Куриную грудку нарежьте полосками, обжарьте 7-8 минут. Добавьте чеснок и овощи, жарьте ещё 5 минут. Посолите и поперчите.', 20, 1, 285, 38.0, 12.0, 8.0, 'lunch', '["белковое", "низкоуглеводное", "диетическое"]', true),
('Греческий салат', 'Классический средиземноморский салат', '["200г томатов черри", "1 огурец", "100г сыра фета", "50г маслин", "1/4 красной луковицы", "2 ст.л. оливкового масла", "орегано"]', 'Нарежьте томаты пополам, огурец и лук кольцами. Смешайте в миске. Добавьте маслины и фету, нарезанную кубиками. Заправьте маслом и посыпьте орегано.', 10, 2, 220, 8.0, 10.0, 17.0, 'lunch', '["вегетарианское", "средиземноморское", "быстро"]', true),
('Лосось с киноа', 'Богатый омега-3 и белком ужин', '["150г филе лосося", "80г киноа", "100г шпината", "1 лимон", "1 ст.л. оливкового масла", "соль, перец, укроп"]', 'Отварите киноа 15 минут. Лосось посолите, поперчите, сбрызните лимоном. Запекайте в духовке при 180°C 15 минут. Шпинат обжарьте с маслом 2 минуты. Подавайте лосось с киноа и шпинатом.', 30, 1, 480, 42.0, 35.0, 18.0, 'dinner', '["белковое", "омега-3", "полезное"]', true),
('Смузи с бананом и шпинатом', 'Зелёный смузи для заряда энергии', '["1 банан", "80г шпината", "200мл миндального молока", "1 ст.л. арахисовой пасты", "1 ч.л. семян чиа"]', 'Поместите все ингредиенты в блендер. Измельчите до однородной консистенции. При необходимости добавьте льда или воды для нужной густоты.', 5, 1, 280, 8.0, 42.0, 9.0, 'breakfast', '["веганское", "быстро", "смузи"]', true),
('Яичница с авокадо', 'Богатый полезными жирами завтрак', '["2 яйца", "1 авокадо", "2 тоста из цельнозернового хлеба", "1 помидор", "соль, перец, паприка"]', 'Поджарьте тосты. Разрежьте авокадо, удалите косточку, разомните мякоть вилкой. Посолите и поперчите. Пожарьте яичницу. Намажьте авокадо на тосты, сверху положите яичницу.', 10, 1, 420, 18.0, 32.0, 26.0, 'breakfast', '["белковое", "быстро", "сытное"]', true),
('Суп-пюре из тыквы', 'Согревающий осенний суп с насыщенным вкусом', '["500г тыквы", "1 луковица", "2 зубчика чеснока", "500мл куриного бульона", "100мл кокосового молока", "1 ч.л. имбиря", "соль, перец"]', 'Тыкву и лук нарежьте, обжарьте с чесноком 5 минут. Залейте бульоном, варите 20 минут до мягкости. Добавьте имбирь и кокосовое молоко. Измельчите блендером до однородности.', 35, 4, 160, 4.0, 22.0, 7.0, 'lunch', '["вегетарианское", "суп", "согревающее"]', true),
('Куриные котлеты на пару', 'Диетические котлеты без лишнего жира', '["400г куриного фарша", "1 яйцо", "2 ст.л. овсяных хлопьев", "1 луковица", "соль, перец, зелень"]', 'Смешайте фарш с яйцом, измельчённым луком и овсянкой. Посолите и поперчите. Сформируйте котлеты. Готовьте в пароварке 20 минут.', 30, 4, 195, 28.0, 8.0, 5.0, 'dinner', '["диетическое", "белковое", "на пару"]', true);
INSERT INTO mental_health_podcasts (title, description, duration, popularity_count) VALUES
('Медитация для начинающих', 'Пошаговое введение в практику медитации. Научитесь успокаивать ум и находить внутреннее равновесие всего за 10 минут в день.', '12:30', 1450),
('Техники управления тревогой', 'Практические инструменты для снижения тревожности в стрессовых ситуациях. Дыхательные упражнения и когнитивные техники.', '18:45', 2100),
('Сила позитивного мышления', 'Как переосмыслить негативные мысли и выработать оптимистичный взгляд на жизнь. Основы когнитивно-поведенческой терапии.', '22:10', 980),
('Осознанность в повседневной жизни', 'Как практиковать mindfulness в обычных делах: еде, прогулке, общении. Простые техники для снижения стресса.', '15:20', 1670),
('Работа со страхами и фобиями', 'Понимание природы страха и методы его преодоления. Постепенная экспозиция и переосмысление угроз.', '25:00', 760),
('Эмоциональный интеллект', 'Как распознавать и управлять своими эмоциями. Развитие эмпатии и навыков эмоциональной регуляции.', '20:15', 1230);
