INSERT INTO notifications (user_id, type, title, message, is_read, created_at) VALUES
(2, 'reminder', 'Время выпить воду!', 'Вы выпили только 4 из 8 стаканов воды сегодня. Не забывайте про гидратацию!', false, NOW() - INTERVAL '2 hours'),
(2, 'achievement', 'Серия 5 дней!', 'Поздравляем! Вы выполняете утреннюю зарядку 5 дней подряд. Так держать!', true, NOW() - INTERVAL '1 day'),
(2, 'info', 'Новая статья', 'Опубликована новая статья: «Управление стрессом через питание». Читайте в разделе Библиотека.', true, NOW() - INTERVAL '2 days'),
(3, 'reminder', 'Не забудьте про тренировку', 'Сегодня по плану: Силовая на грудь и трицепс. Удачи!', false, NOW() - INTERVAL '3 hours'),
(3, 'info', 'Подписка активна', 'Ваш план Basic активен до конца квартала. Upgrade для доступа ко всем функциям.', true, NOW() - INTERVAL '15 days');
INSERT INTO chats (user_id, role, content, created_at) VALUES
(2, 'user', 'Привет! Помоги мне составить план питания для похудения', NOW() - INTERVAL '3 days'),
(2, 'assistant', 'Привет, Анна! Рада помочь. Для эффективного похудения важно создать небольшой дефицит калорий — около 300-500 ккал в день. При вашем весе 68.5 кг и умеренной активности рекомендую около 1600-1700 ккал в день. Сосредоточьтесь на белке (130-140г), он помогает сохранить мышцы и даёт сытость. Хотите, я предложу примерное меню на день?', NOW() - INTERVAL '3 days' + INTERVAL '1 minute'),
(2, 'user', 'Да, покажи меню на день пожалуйста', NOW() - INTERVAL '3 days' + INTERVAL '2 minutes'),
(2, 'assistant', 'Вот примерное меню на 1600 ккал:\n\n🌅 Завтрак (350 ккал): Овсяная каша с ягодами + чай без сахара\n\n🍎 Перекус (150 ккал): Яблоко + горсть миндаля (15г)\n\n🥗 Обед (400 ккал): Куриная грудка 150г + салат из свежих овощей + 2 хлебца\n\n☕ Полдник (100 ккал): Нежирный йогурт 150г\n\n🍽 Ужин (450 ккал): Запечённый лосось с киноа и шпинатом\n\nИтого: ~1450-1600 ккал, белок ~140г. Пейте 1.5-2 литра воды!', NOW() - INTERVAL '3 days' + INTERVAL '3 minutes'),
(2, 'user', 'Спасибо! А как часто нужно тренироваться?', NOW() - INTERVAL '2 days'),
(2, 'assistant', 'Для похудения оптимально 4-5 тренировок в неделю. Рекомендую такую схему:\n\n💪 Пн/Ср/Пт — силовые тренировки (40-50 мин). Они разгоняют метаболизм на 24-48 часов после тренировки!\n\n🏃 Вт/Чт — лёгкое кардио (30-40 мин): прогулка быстрым шагом или велосипед\n\n😴 Выходные — активный отдых или растяжка\n\nГлавное — не пропускать! Даже 20 минут лучше, чем ничего. Вы уже занимаетесь зарядкой каждое утро — это отличная база!', NOW() - INTERVAL '2 days' + INTERVAL '1 minute');
